INSERT INTO `sms` (`id`, `subject`, `message`, `is_designation_wise`, `designations`, `action`, `status`) VALUES
(1, 'complain_received_confirmation_SMS_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, your complain \"<!--df_problem-->\" received by polar customer service department. We will resolve it shortly. Thanks, Polar Ice-cream', 0, NULL, 'problemEntry', 'active'),
(2, 'new_complain_SMS_for_teamleader', 'Date: <!--created_date-->, Time: <!--created_time-->, Outlet Name: <!--outlet_name-->, Address:  <!--address-->, Mobile: <!--mobile-->, Problem: <!--df_problem-->, DF Size: <!--df_size-->, DF code: <!--df_code-->, Depot: <!--depot-->, Region: <!--region-->. Thanks, <!--sender-->', 1, '[\"27\",\"37\"]', 'problemEntry', 'active'),
(3, 'complain_SMS_for_assigned_technician', 'Date: <!--created_date-->, Time: <!--created_time-->, Outlet Name: <!--outlet_name-->,  Address: <!--address-->, Mobile: <!--mobile-->, Problem: <!--df_problem-->, DF Size: <!--df_size-->, DF Code: <!--df_code-->, Depot: <!--depot-->, Region: <!--region-->. Thanks, <!--sender-->', 0, NULL, 'assignTechnician', 'inactive'),
(4, 'complain_resolved_SMS_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, your complain \"<!--df_problem-->\" has been resolved by polar service department. For further clarification please let us know. Thanks, Polar Ice-cream', 0, NULL, 'problemEntryEdit_for_complete', 'active'),
(5, 'complain_resolved_SMS_for_executive', 'Dear Mr. <!--sender-->, The complain for the \"<!--outlet_name-->\" DF Size: <!--df_size-->, DF Code: <!--df_code-->, has been resolved. Please inform your outlet owner. Thanks, Polar Ice-cream', 0, NULL, 'problemEntryEdit_for_complete', 'active'),
(6, 'need_to_pull_sms_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, your complain \"<!--df_problem-->\" has not resolved on spot and we need to pulled up the DF into our workshop. Polar responsible person will communicate with you soon. Thanks, Polar Ice-cream', 0, NULL, 'problemEntryEdit_for_pull', 'active'),
(7, 'df_return_application_approved_sms_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, your return application has been approved for DF Code: <!--df_code--> . Your payable amount is TK <!--payable_amount-->, Thanks, Polar Ice-cream', 0, NULL, 'problemEntryEdit_for_pull', 'active'),
(8, 'requisition_hold_SMS_for_executive', 'Dear Mr. <!--sender-->, your requisition has been hold for the <!--outlet_name-->. <!--comments-->. Thanks, <!--from-->', 0, NULL, 'requisition_hold', 'active'),
(9, 'requisition_cancel_SMS_for_executive', 'Dear Mr. <!--sender-->, your requisition has been cancelled for the <!--outlet_name-->. <!--comments-->. Thanks, <!--from-->', 0, NULL, 'requisition_cancel', 'active'),
(10, 'requisition_final_approved_SMS_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, your requisition for new DF has been approved. Our respective officer will communicate with you shortly. Thanks, Polar Ice-cream', 0, NULL, 'requisition_approve', 'inactive'),
(11, 'requisition_final_approved_SMS_for_executive', 'Dear Mr. <!--sender-->, your requisition for new DF has been approved for the <!--outlet_name-->. Take essential steps.', 0, NULL, 'requisition_approve', 'active'),
(12, 'bkash_payment_confirmation_SMS_shop_owner', 'Dear valuable customer <!--proprietor_name-->, Outlet: <!--outlet_name-->, we have received your payment of TK \"<!--receive_amount-->\" for DF service rent purpose. Thanks, Polar Ice-cream', 0, NULL, 'putTransactionId', 'active'),
(13, 'payable_confirmation_SMS_for_shop_owner', 'Dear valuable customer <!--proprietor_name-->, your settlement has been closed for the Outlet: <!--outlet_name-->, DF Code: <!--df_code--> and your receivable TK is \"<!--paid_amount-->\". Please collect your payment. Thanks, Polar Ice-cream', 0, NULL, 'payToOutlet', 'inactive'),
(14, 'payable_confirmation_SMS_for_executive', 'Dear Mr. <!--sender-->, settlement has been closed for the Outlet: <!--outlet_name-->, DF Code: <!--df_code--> and receivable TK is \"<!--paid_amount-->\". Take necessary steps. Thanks, Polar Ice-cream', 0, NULL, 'payToOutlet_executive', 'inactive');
INSERT INTO `sms_promotionals` (`id`, `user_id`, `depots`, `receiver_group`, `subject`, `message`, `type`, `created_at`) VALUES
(1, 46, '[\"3\", \"4\", \"5\"]', '[\"1\", \"5\", \"11\", \"12\", \"13\", \"23\", \"26\", \"29\", \"31\", \"32\"]', 'Data Maintenance 01', 'Dear Team\r\nDue to FDMS software maintenance, requisition & completed process is down. After update we will come back soon.\r\nThanks', 'sales_team', '2019-02-27 09:27:50'),
(2, 46, '[\"3\", \"4\", \"5\"]', '[\"1\", \"5\", \"11\", \"12\", \"13\", \"16\", \"19\", \"23\", \"25\", \"26\", \"29\", \"31\", \"32\"]', 'Data Maintenance 02', 'Dear Team\r\nFDMS data migration for your region is successfully done. From now and onward you can work smoothly in the software.\r\nThanks', 'sales_team', '2019-03-03 14:59:33'),
(3, 46, '[\"3\", \"4\", \"5\"]', '[\"1\", \"2\", \"11\", \"12\", \"13\", \"16\", \"25\", \"26\", \"27\", \"29\", \"31\", \"32\"]', 'DF Service live for DW1, DW2 & DE', 'Dear\r\nYou will be happy to know that our FDMS service module will be live from tomorrow (5th March). Hopeful you will enjoy the full automation system.\r\nThanks', 'sales_team', '2019-03-04 12:10:19'),
(4, 46, '[\"3\", \"4\", \"5\"]', '[\"5\", \"15\", \"25\"]', 'New DF Allocation 24 Mar', 'Dear A/C,\r\nSome new DF is delivered to your depot from CTG port.After receive the DF physically please input the feedback & receive the DF in your FDMS.\r\nThanks', 'sales_team', '2019-03-24 06:58:41'),
(5, 46, '[\"3\"]', '[\"25\"]', 'Test', 'Dear TEAM,\r\n\r\nFrom now you can select multiple complain entry under a single token number. So if there are several complain select more.\r\n\r\nThanks', 'sales_team', '2019-03-31 09:14:49'),
(6, 46, '[\"3\"]', '[\"25\"]', 'Test 2', 'Dear TEAM,\r\n\r\nFrom now you can select multiple complain entry under a single token number. So if there are several complain select more.\r\nAnd when you select the requisition is \"replace\" then a box will show for wright the \"Replace Reason\". \r\n\r\nIf you have any query please let me know. \r\nThanks\r\nRiyadh', 'sales_team', '2019-03-31 09:18:50'),
(7, 46, '[\"3\", \"4\", \"5\"]', '[\"1\", \"2\", \"11\", \"12\", \"13\", \"16\", \"26\", \"27\", \"29\", \"31\", \"32\", \"37\"]', 'Modification 01', 'Dear TEAM,\r\n\r\nFrom now you can select multiple complain entry under a single token number. So if there are any several complain select more from option.\r\nAnd when you select the requisition is \"replace\" then a box will show for input the \"Replace Reason\".\r\nIf you have any query please let me know. \r\nThanks\r\nRiyadh', 'sales_team', '2019-03-31 09:21:41');
